package travel

/** Python 3.11 Unicode mappings generated by tools/generate_unicode.py. */
object PyStr {
    private fun lines(name: String): Sequence<String> =
        requireNotNull(PyStr::class.java.classLoader.getResourceAsStream("unicode/$name.tsv"))
            .bufferedReader(Charsets.UTF_8).use { it.readLines() }.asSequence()
            .filter { !it.startsWith("#") && it.isNotEmpty() }
    private fun table(name: String) = lines(name).associate { line ->
        val columns = line.split('\t')
        columns[0].toInt(16) to columns[1].split(' ').joinToString("") { String(Character.toChars(it.toInt(16))) }
    }
    private val lowerTable by lazy { table("lower") }
    private val casefoldTable by lazy { table("casefold") }
    private val cased by lazy { lines("cased").map { it.toInt(16) }.toSet() }
    private val caseIgnorable by lazy { lines("case_ignorable").map { it.toInt(16) }.toSet() }
    private fun convert(value: String, mapping: Map<Int, String>, contextual: Boolean): String {
        val points = value.codePoints().toArray()
        return buildString {
            for (i in points.indices) {
                val cp = points[i]
                if (contextual && cp == 0x03A3) {
                    var before = i - 1
                    while (before >= 0 && points[before] in caseIgnorable) before--
                    var after = i + 1
                    while (after < points.size && points[after] in caseIgnorable) after++
                    val final = before >= 0 && points[before] in cased && (after == points.size || points[after] !in cased)
                    append(if (final) '\u03c2' else '\u03c3')
                } else append(mapping[cp] ?: String(Character.toChars(cp)))
            }
        }
    }
    // Port of CPython 3.11 unicodeobject.c:handle_capital_sigma and lower_ucs4.
    fun lower(value: String): String = convert(value, lowerTable, true)
    fun casefold(value: String): String = convert(value, casefoldTable, false)
}
